CREATE DATABASE IF NOT EXISTS imhotep CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE imhotep;
CREATE TABLE IF NOT EXISTS almacenes (id INT PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(60) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS trabajadores (id VARCHAR(30) PRIMARY KEY, nombre VARCHAR(120) NOT NULL, area VARCHAR(80) NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS articulos (id VARCHAR(40) PRIMARY KEY, nombre VARCHAR(120) NOT NULL, tipo ENUM('pieza','consumible') NOT NULL, limite INT NOT NULL DEFAULT 1, requiere_inspeccion BOOLEAN NOT NULL DEFAULT FALSE, CHECK(limite>0));
CREATE TABLE IF NOT EXISTS piezas (id VARCHAR(40) PRIMARY KEY, articulo_id VARCHAR(40) NOT NULL, almacen_id INT NULL, estado ENUM('apto','no_apto') NOT NULL DEFAULT 'apto', inspeccion_hasta DATE NULL, trabajador_id VARCHAR(30) NULL, FOREIGN KEY(articulo_id) REFERENCES articulos(id), FOREIGN KEY(almacen_id) REFERENCES almacenes(id), FOREIGN KEY(trabajador_id) REFERENCES trabajadores(id));
CREATE TABLE IF NOT EXISTS existencias (articulo_id VARCHAR(40) NOT NULL, almacen_id INT NOT NULL, cantidad INT NOT NULL DEFAULT 0, PRIMARY KEY(articulo_id,almacen_id), FOREIGN KEY(articulo_id) REFERENCES articulos(id), FOREIGN KEY(almacen_id) REFERENCES almacenes(id), CHECK(cantidad>=0));
CREATE TABLE IF NOT EXISTS movimientos (id BIGINT PRIMARY KEY AUTO_INCREMENT, folio VARCHAR(40) NOT NULL UNIQUE, tipo ENUM('entrega','devolucion','traspaso') NOT NULL, articulo_id VARCHAR(40) NOT NULL, pieza_id VARCHAR(40) NULL, trabajador_id VARCHAR(30) NULL, origen_id INT NULL, destino_id INT NULL, cantidad INT NOT NULL, responsable VARCHAR(80) NOT NULL, fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(articulo_id) REFERENCES articulos(id), FOREIGN KEY(pieza_id) REFERENCES piezas(id), FOREIGN KEY(trabajador_id) REFERENCES trabajadores(id), FOREIGN KEY(origen_id) REFERENCES almacenes(id), FOREIGN KEY(destino_id) REFERENCES almacenes(id), CHECK(cantidad>0));
CREATE TABLE IF NOT EXISTS autorizaciones (id BIGINT PRIMARY KEY AUTO_INCREMENT, trabajador_id VARCHAR(30) NOT NULL, articulo_id VARCHAR(40) NOT NULL, cantidad INT NOT NULL, supervisor VARCHAR(80) NOT NULL, motivo VARCHAR(255) NOT NULL, usada BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(trabajador_id) REFERENCES trabajadores(id), FOREIGN KEY(articulo_id) REFERENCES articulos(id));
